        independent->begin("Retime source");s.lanes[actor].frames[0].ticks=10;independent->commit();CHECK(!scene_uses_lane(s,s.lanes[actor].id)&&row.frames[0].visible_from==4);independent->undo();CHECK(s.lanes[actor].frames[0].ticks==4&&!s.lanes[effect].trigger_lane&&independent->import_notes().size()==1);independent->redo();CHECK(s.lanes[actor].frames[0].ticks==10);independent->undo();
        CHECK(!independent->save((root/"missing"/"out.ISTUDIO").u8string(),source,error)&&independent->import_notes().size()==1);CHECK(independent->export_png((root/"before.png").u8string(),5,source,error));CHECK(independent->save((root/"out.ISTUDIO").u8string(),source,error)&&independent->import_notes().empty());auto saved=read(root/"out.ISTUDIO");CHECK(expected->save((root/"expected.ISTUDIO").u8string(),source,error)&&read(root/"expected.ISTUDIO")==saved);
        auto round=SceneProject::read((root/"out.ISTUDIO").u8string(),error);CHECK(round&&round->bind(binder,issues));if(round){CHECK(round->import_notes().empty()&&!round->imported_wax());for(int tick:{0,3,4,5,6,7,8,9,12,20,50})CHECK(same_poses(s,round->state,tick));CHECK(round->export_png((root/"after.png").u8string(),5,source,error)&&read(root/"after.png")==read(root/"before.png"));CHECK(round->save((root/"out.ISTUDIO").u8string(),source,error)&&read(root/"out.ISTUDIO")==saved);}
