    auto zero_hold=base;set(zero_hold,"slot.1.hold","0");set(zero_hold,"slot.1.visible_from","4,8");set(zero_hold,"slot.1.visible_until","8,12");auto fallback=load(zero_hold);CHECK(fallback&&fallback->import_notes().empty()&&fallback->state.lanes[lane(fallback->state,2)].trigger_lane);
