    auto wrong=base;set(wrong,"slot.1.visible_from","4,7");set(wrong,"slot.1.spawn_slot","2");CHECK(!load(wrong));set(wrong,"slot.1.spawn_slot","0");set(wrong,"slot.1.spawn_entry","-1");CHECK(!load(wrong));
