    CHECK(art->selection_id()==selected&&art->disk_version()==version&&read(root/"actor.IMG")==bytes&&g_doc==nullptr);CHECK(fs::weakly_canonical(root).parent_path()==fs::weakly_canonical(parent));if(fs::weakly_canonical(root).parent_path()==fs::weakly_canonical(parent))fs::remove_all(root);std::cout<<"WAX authored timing: "<<failures<<" failure(s)\n";return failures?1:0;
